from fractions import Fraction
import math

def dyadic_mean(n):
    """E[phi_n] for X = U^2, where phi_n = floor(2^n X) / 2^n."""
    N = 2 ** n
    return sum(k / N * (math.sqrt((k + 1) / N) - math.sqrt(k / N)) for k in range(N))

def simple_mean(values, probs):
    """Exact mean of a simple function: values[k] taken with chance probs[k] (Fractions)."""
    return sum((a * p for a, p in zip(values, probs)), Fraction(0))
